        nextTool === "farm"
          ? `${CROP_LABELS[selectedCropRef.current]}农场营造：选择一块 2×2 空地`
          : toolInstructions[nextTool],
      );
    } else {
      setFeedback("已退出营造模式");
      rendererRef.current?.setPlacementPreview(null, "hidden");
      setPlacementStatus("hidden");
    }
  };

