          </div>
          <div>
            <dt>人流</dt>
            <dd data-testid="citizen-activity">{citizenActivity}</dd>
          </div>
          <div>
            <dt>水井</dt>
            <dd data-testid="well-count">{wellCount}</dd>
          </div>
          <div>
