@media (max-width: 1500px) {
  .top-bar {
    align-items: center;
    padding: 10px 24px;
  }

  .hud {
    display: grid;
    grid-template-columns: repeat(15, minmax(44px, 68px));
    gap: 3px;
  }

  .hud div {
    min-width: 0;
    padding: 3px 5px;
  }

  .hud dt {
    margin-bottom: 1px;
    font-size: 8px;
  }

  .hud dd {
    font-size: 10px;
  }
}

@media (max-width: 640px) {
  .top-bar {
    min-height: 72px;
    padding: 12px;
  }

  h1 {
    font-size: 22px;
  }

  .hud {
    grid-template-columns: repeat(5, minmax(44px, 58px));
  }

  .hud dt {
    margin-bottom: 1px;
    font-size: 8px;
  }

  .hud dd {
    font-size: 10px;
  }

  .build-dock {
    left: 12px;
    bottom: 58px;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    width: 176px;
  }

  .crop-picker {
    left: 12px;
    bottom: 330px;
    max-width: calc(100vw - 24px);
    overflow-x: auto;
  }

  .speed-panel {
    left: 196px;
    bottom: 58px;
  }

  .labor-panel {
    right: 12px;
    bottom: 58px;
    max-width: calc(100vw - 212px);
    overflow-x: auto;
  }

  .storage-panel {
    right: 12px;
    bottom: 98px;
    max-width: calc(100vw - 212px);
    overflow-x: auto;
  }

  .religion-panel {
    right: 12px;
    bottom: 138px;
  }

  .diplomacy-panel {
    right: 12px;
    bottom: 178px;
    max-width: calc(100vw - 212px);
    overflow-x: auto;
  }

  .status-ribbon {
    right: 12px;
    bottom: 10px;
    left: 12px;
    overflow-x: auto;
  }

  .status-ribbon span {
    flex: 0 0 auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}
