}

.population-row-label {
  color: var(--mist);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 10px;
  letter-spacing: 0.06em;
}

.population-row-value {
  color: var(--paper);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
}

@media (prefers-reduced-motion: reduce) {
  .stat-clickable {
    transition: none;
  }
}

@media (max-width: 900px) {
  .population-panel {
    right: 12px;
    width: 280px;
  }
}
