  "originalFile": ":root {
  --ink: #071214;
  --tile-ink: #163032;
  --pine: #667f58;
  --timber: #7c4024;
  --paper: #eee2bf;
  --bronze: #b89a55;
  --market-red: #ad4b32;
  --mist: #a9b5a4;
  color: var(--paper);
  background: var(--ink);
  font-family: "Noto Sans SC", "PingFang SC", "Microsoft YaHei", sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

* {
  box-sizing: border-box;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

html,
body,
#root {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
}

button {
  font: inherit;
}

.game-shell {
  position: relative;
  width: 100%;
  height: 100%;
  isolation: isolate;
  background:
    radial-gradient(circle at 50% 30%, rgb(102 127 88 / 20%), transparent 48%),
    var(--ink);
}

.game-shell::after {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  content: "";
  background: linear-gradient(
    180deg,
    rgb(4 8 10 / 58%),
    transparent 18%,
    transparent 76%,
    rgb(4 8 10 / 70%)
  );
}

.game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  outline: none;
  touch-action: none;
}

.top-bar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 88px;
  pointer-events: none;
  padding: 16px 24px;
  border-bottom: 1px solid rgb(184 154 85 / 24%);
  background: linear-gradient(180deg, rgb(7 18 20 / 96%), rgb(13 30 31 / 76%));
  backdrop-filter: blur(12px);
  gap: 16px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--bronze);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  color: var(--paper);
  font-family: "Songti SC", STSong, serif;
  font-size: 30px;
  font-weight: 600;
  letter-spacing: 0.14em;
}

.hud {
  display: flex;
  gap: 8px;
  margin: 0;
}

.hud div {
  min-width: 84px;
  padding: 8px 12px;
  border: 1px solid rgb(184 154 85 / 20%);
  border-radius: 0;
  background: rgb(22 48 50 / 62%);
  clip-path: polygon(0 0, calc(100% - 6px) 0, 100% 6px, 100% 100%, 0 100%);
}

.hud dt {
  margin-bottom: 3px;
  color: var(--mist);
  font-size: 10px;
  letter-spacing: 0.12em;
}

.hud dd {
  margin: 0;
  color: var(--paper);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 13px;
}

.build-dock {
  position: absolute;
  left: 24px;
  bottom: 52px;
  z-index: 5;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  width: 270px;
  padding: 8px;
  border: 1px solid rgb(184 154 85 / 35%);
  border-radius: 0;
  background: rgb(8 23 24 / 93%);
  box-shadow: 0 18px 40px rgb(0 0 0 / 32%);
  gap: 6px;
  clip-path: polygon(
    0 0,
    calc(100% - 8px) 0,
    100% 8px,
    100% 100%,
    8px 100%,
    0 calc(100% - 8px)
  );
}

.dock-label {
  display: block;
  grid-column: 1 / -1;
  margin: 0 0 0 2px;
  color: var(--bronze);
  font-size: 11px;
  letter-spacing: 0.16em;
}

.build-dock button {
  display: grid;
  width: 100%;
  padding: 5px;
  color: #827d70;
  border: 1px solid rgb(184 170 132 / 15%);
  border-radius: 3px;
  background: #111d1e;
  cursor: not-allowed;
  gap: 3px;
  place-items: center;
}

.build-dock button:not(:disabled) {
  color: #d8d0b8;
  border-color: rgb(204 181 116 / 38%);
  cursor: pointer;
}

.build-dock button:not(:disabled):hover,
.build-dock button.active {
  color: var(--paper);
  border-color: var(--bronze);
  background: #274539;
  box-shadow: inset 0 0 0 1px rgb(255 231 167 / 8%);
}

.build-dock button.well-tool .building-glyph {
  color: #71aebc;
}

.build-dock button.well-tool:not(:disabled):hover,
.build-dock button.well-tool.active {
  color: #e2f3ee;
  border-color: #71aebc;
  background: #173c43;
}

.build-dock button.farm-tool .building-glyph {
  color: #c7ad50;
}

.build-dock button.farm-tool:not(:disabled):hover,
.build-dock button.farm-tool.active {
  color: #f1e7b5;
  border-color: #a9a84e;
  background: #34452a;
}

.build-dock button.granary-tool .building-glyph {
  color: #bd7549;
}

.build-dock button.granary-tool:not(:disabled):hover,
.build-dock button.granary-tool.active {
  color: #f0d7bc;
  border-color: #bd7549;
  background: #452d20;
}

.build-dock button.market-tool .building-glyph {
  color: #d06a4b;
}

.build-dock button.market-tool:not(:disabled):hover,
.build-dock button.market-tool.active {
