  border-color: var(--market-red);
  background: #4a2822;
}

.build-dock button.hemp-tool .building-glyph {
  color: #8eb260;
}

.build-dock button.hemp-tool:not(:disabled):hover,
.build-dock button.hemp-tool.active {
  color: #e0edbd;
  border-color: #8eb260;
  background: #29452a;
}

.build-dock button.weaver-tool .building-glyph {
  color: #c49a70;
}

.build-dock button.weaver-tool:not(:disabled):hover,
.build-dock button.weaver-tool.active {
  color: #f0ddca;
  border-color: #c49a70;
  background: #453528;
}

.build-dock button.weaponsmith-tool .building-glyph {
  color: #d48755;
}

.build-dock button.weaponsmith-tool:not(:disabled):hover,
.build-dock button.weaponsmith-tool.active {
  color: #f2d1b6;
  border-color: #d48755;
  background: #4a2d22;
}

.build-dock button.fort-tool .building-glyph {
  color: #c86852;
}

.build-dock button.fort-tool:not(:disabled):hover,
.build-dock button.fort-tool.active {
  color: #f1cdc4;
  border-color: #c86852;
  background: #472722;
}

.build-dock button.tax-tool .building-glyph {
  color: #c3a75f;
}

.build-dock button.tax-tool:not(:disabled):hover,
.build-dock button.tax-tool.active {
  color: #f0dfaa;
  border-color: #9d8549;
  background: #40361f;
}

.build-dock button.music-tool .building-glyph {
  color: #bc7990;
}

.build-dock button.music-tool:not(:disabled):hover,
.build-dock button.music-tool.active {
  color: #f0c6d2;
  border-color: #9b6074;
  background: #3d2730;
}

.build-dock button.trade-tool .building-glyph {
  color: #77a48f;
}

.build-dock button.trade-tool:not(:disabled):hover,
.build-dock button.trade-tool.active {
  color: #cce4d8;
  border-color: #608c79;
  background: #263d34;
}

.build-dock button.demolish-tool {
  grid-column: 1 / -1;
  grid-template-columns: auto auto;
  justify-content: center;
  min-height: 42px;
}

.build-dock button.demolish-tool .building-glyph {
  width: 28px;
  height: 28px;
  font-size: 17px;
}

.building-glyph {
  display: grid;
  width: 34px;
  height: 34px;
  color: #9d947e;
  border: 1px solid currentColor;
  place-items: center;
  font-family: "Songti SC", STSong, serif;
  font-size: 20px;
}

.crop-picker {
  position: absolute;
  left: 302px;
  bottom: 104px;
  z-index: 5;
  display: flex;
  align-items: stretch;
  padding: 7px;
  border: 1px solid rgb(184 154 85 / 35%);
  background: rgb(8 23 24 / 94%);
  box-shadow: 0 16px 34px rgb(0 0 0 / 30%);
  gap: 5px;
}

.crop-picker-title {
  display: grid;
  padding: 0 8px;
  color: var(--bronze);
  font-family: "Songti SC", STSong, serif;
  font-size: 12px;
  letter-spacing: 0.1em;
  place-items: center;
}

.crop-picker button {
  display: grid;
