        "+  const tile = { x, y };",
        "+  if (",
        "+    snapshot.roads.some((road) => road.x === x && road.y === y) ||",
        "+    snapshot.buildings.some((building) => tileInsideBuilding(tile, building))",
        "+  ) {",
