        "+      priorities: [...world.laborPolicy.priorities],",
        "+    },",
        "+    shennongFavor: world.shennongFavor,",
        "+    diplomacy: {",
        "+      ...world.diplomacy,",
        "+      envoys: world.diplomacy.envoys.map((envoy) => ({ ...envoy })),",
