        "+",
        "+function rejected(",
        "+  world: WorldState,",
        "+  seq: number,",
        "+  reasonCode:",
        "+    | "occupied"",
        "+    | "out-of-bounds"",
        "+    | "invalid-path"",
        "+    | "nothing-to-demolish"",
        "+    | "not-found"",
        "+    | "insufficient-stock"",
        "+    | "insufficient-funds"",
        "+    | "requirements-not-met"",
        "+    | "counter-exhausted",",
        "+): CommandApplication {",
        "+  return {",
        "+    result: { seq, accepted: false, reasonCode },",
        "+    snapshot: snapshotWorld(world),",
        "+  };",
        "+}",
        "+",
        "+function accepted(world: WorldState, seq: number): CommandApplication {",
        "+  return {",
        "+    result: {",
        "+      seq,",
        "+      accepted: true,",
        "+      appliedAtTick: world.tick,",
        "+      revision: world.revision,",
        "+    },",
        "+    snapshot: snapshotWorld(world),",
        "+  };",
        "+}",
        "+",
        "+function applyBuildCommand(",
        "+  world: WorldState,",
        "+  command: Extract<GameCommand, { type: "build" }>,",
