        "+      map: { width: MAP_SIZE, height: MAP_SIZE },",
        "+      buildings: world.buildings,",
        "+      roads: world.roads,",
        "+    },",
        "+    command.buildingTypeId,",
        "+    command.x,",
        "+    command.y,",
