        "+      (building) =>",
        "+        building.id === command.granaryId && building.typeId === "granary",",
        "+    );",
        "+    if (!granary || granary.typeId !== "granary") {",
        "+      return rejected(world, command.seq, "not-found");",
        "+    }",
        "+    if (granary.foodStocks[command.cropType] <= 0) {",
