        "+      if (farm.hempStock < 3) farm.hempStock += 1;",
        "+    }",
        "+  }",
        "+",
        "+  for (const weaver of weavers) {",
        "+    if (weaver.hempStock >= 2) continue;",
        "+    const source = hempFarms",
        "+      .filter((farm) => farm.hempStock > 0)",
        "+      .map((farm) => ({",
        "+        farm,",
