        "+        (left, right) =>",
        "+          left.distance - right.distance || left.farm.id - right.farm.id,",
        "+      )[0]?.farm;",
        "+    if (source) {",
        "+      source.hempStock -= 1;",
        "+      weaver.hempStock += 1;",
        "+    }",
        "+    if (weaver.hempStock > 0 && weaver.clothingStock < 2) {",
