/* ---- Population Detail Panel ---- */

.stat-clickable {
  cursor: pointer;
  transition: border-color 0.15s;
  pointer-events: auto;
}

.stat-clickable:hover,
.stat-clickable.active {
  border-color: rgb(204 181 116 / 64%);
  background: rgb(34 72 76 / 72%);
}

.population-panel {
  position: absolute;
  top: 104px;
  right: 24px;
  bottom: 52px;
  z-index: 6;
  width: 340px;
  overflow: hidden;
  pointer-events: auto;
  border: 1px solid rgb(184 154 85 / 35%);
  background: rgb(8 23 24 / 95%);
  box-shadow: 0 18px 40px rgb(0 0 0 / 48%);
  clip-path: polygon(
    0 0,
    calc(100% - 8px) 0,
    100% 8px,
    100% 100%,
    8px 100%,
    0 calc(100% - 8px)
  );
}

.population-panel-close {
  position: absolute;
  top: 8px;
  right: 10px;
  z-index: 1;
  display: grid;
  width: 26px;
  height: 26px;
  padding: 0;
  color: var(--bronze);
  border: 1px solid rgb(184 154 85 / 25%);
  border-radius: 2px;
  background: rgb(17 29 30 / 90%);
  cursor: pointer;
  font-size: 14px;
  line-height: 1;
  place-items: center;
  transition: color 0.15s, border-color 0.15s;
}

.population-panel-close:hover {
  color: var(--paper);
  border-color: var(--bronze);
}

.population-panel-inner {
  height: 100%;
  overflow-y: auto;
  padding: 16px 20px;
  scrollbar-width: thin;
  scrollbar-color: rgb(184 154 85 / 30%) transparent;
}

.population-section {
  margin-bottom: 20px;
}

.population-section-title {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 10px;
  color: var(--paper);
  font-family: "Songti SC", STSong, serif;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.08em;
}

.population-section-count {
  color: var(--bronze);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
  font-weight: 400;
}

.population-empty {
  margin: 0;
  padding: 16px 0;
  color: var(--mist);
  font-size: 12px;
  font-style: italic;
}

.population-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 8px;
}

.population-card {
  padding: 10px 12px;
  border: 1px solid rgb(184 170 132 / 15%);
  background: rgb(17 29 30 / 80%);
}

.population-card-header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid rgb(184 154 85 / 12%);
}

.population-card-icon {
  font-size: 14px;
  line-height: 1;
}

.population-card-label {
  color: var(--paper);
  font-size: 12px;
  font-weight: 600;
}

.population-card-state {
  margin-left: auto;
  padding: 2px 6px;
  border-radius: 2px;
  font-size: 10px;
  letter-spacing: 0.06em;
}

.population-card-state.walking,
.population-card-state.commuting {
  color: #8abbc6;
  border: 1px solid rgb(138 187 198 / 30%);
  background: rgb(138 187 198 / 10%);
}

.population-card-state.building {
  color: #d4b47a;
  border: 1px solid rgb(212 180 122 / 30%);
  background: rgb(212 180 122 / 10%);
}

.population-card-state.working {
  color: #8cc76f;
  border: 1px solid rgb(140 199 111 / 30%);
  background: rgb(140 199 111 / 10%);
}

.population-card-state.returning {
  color: #c7a06f;
  border: 1px solid rgb(199 160 111 / 30%);
  background: rgb(199 160 111 / 10%);
}

.population-card-state.resting {
  color: #a9b5a4;
  border: 1px solid rgb(169 181 164 / 30%);
  background: rgb(169 181 164 / 10%);
}

.population-card-state.strolling {
  color: #b5b0a4;
  border: 1px solid rgb(181 176 164 / 30%);
  background: rgb(181 176 164 / 10%);
}

.population-card-state.waiting {
  color: #c67a7a;
  border: 1px solid rgb(198 122 122 / 30%);
  background: rgb(198 122 122 / 10%);
}

.population-card-body {
  display: grid;
  gap: 4px;
}

.population-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 11px;
}

.population-row-label {
  color: var(--mist);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 10px;
  letter-spacing: 0.06em;
}

.population-row-value {
  color: var(--paper);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
}

@media (prefers-reduced-motion: reduce) {
  .stat-clickable {
    transition: none;
  }
}

@media (max-width: 900px) {
  .population-panel {
    right: 12px;
    width: 280px;
  }
}
