        />
        <ConditionRow
          label="供水服务"
          ok={hasWater}
          okText="已覆盖"
          failText="未覆盖 — 8格内无水井"
        />
        <ConditionRow
          label="五行元素"
          value={elementLabels[element]}
        />
        <ConditionRow
          label="风水格局"
          value={`${fengShui.fiveElement} · ${{
            auspicious: "吉",
            neutral: "平",
            inauspicious: "凶",
          }[fengShui.status]}`}
        />
        <ConditionRow
          label="宜居度"
          value={`${desirability}`}
