    case "citizen":
      return (
        <CitizenDetail
          citizen={entity.citizen}
          house={entity.house}
          workplace={entity.workplace}
        />
      );
    case "household":
      return (
        <HouseholdDetail
          household={entity.household}
          house={entity.house}
          snapshot={snapshot}
        />
      );
    case "house":
      return (
        <HouseDetail
          house={entity.house}
          household={entity.household}
          snapshot={snapshot}
        />
      );
  }
}

