        "-          <DetailRow",
        "-            label="施工阶段"",
        "-            value={constructionStageLabel[house.constructionStage]}",
        "-          />",
        "-          <DetailRow",
        "-            label="等级"",
        "-            value={`${house.level} 级`}",
        "-          />",
        "-        </>",
        "-      )}",
        "-    </div>",
        "-  );",
        "-}",
        "-",
        "-// ---- Citizen Detail ----",
        "-",
        "-function CitizenDetail({",
        "-  citizen,",
        "-  house,",
