  const updateOuterTerrain = () => {
    outerTerrain.position.x =
      Math.round(camera.target.x / TERRAIN_REPEAT_WORLD_SIZE) *
      TERRAIN_REPEAT_WORLD_SIZE;
    outerTerrain.position.z =
