        "+    <li",
        "+      className="population-card citizen-card clickable-card"",
        "+      onClick={onClick}",
        "+      onKeyDown={(e) => {",
        "+        if (e.key === "Enter" || e.key === " ") {",
        "+          e.preventDefault();",
        "+          onClick();",
        "+        }",
        "+      }}",
        "+      tabIndex={0}",
