        "+          label="位置"",
        "+          value={house ? `${house.x}, ${house.y}` : "—"}",
        "+        />",
        "+      </div>",
        "+    </li>",
        "+  );",
        "+}",
        "+",
        "+function HouseCard({",
        "+  house,",
        "+  household,",
