        b.typeId === "house" &&
        tile.x >= b.x &&
        tile.x < b.x + b.footprint.width &&
        tile.y >= b.y &&
        tile.y < b.y + b.footprint.height,
    );
    if (house) {
      // Close population panel, open house detail
