        "+            return (",
        "+              <button",
        "+                key={option.type}",
        "+                type="button"",
        "+                className={accepted ? "active" : undefined}",
        "+                aria-pressed={accepted}",
        "+                data-testid={`granary-accept-${option.type}`}",
        "+                onClick={() => toggleGranaryCrop(option.type)}",
        "+              >",
        "+                {option.label}",
        "+              </button>",
        "+            );",
        "+          })}",
        "+        </section>",
        "+      ) : null}",
        "+",
